#!/usr/bin/env bash
# The mlkem512 / mlkem768 / mlkem1024 subcommands against the ACVP ML-KEM known answers.
#
# Written for the 2026-11-03 CLI review (report 15) from the vector files named in each test;
# every expected value is copied from that file, none is typed by hand. Follows lib.sh's
# conventions: each test_* runs in its own subshell under `set -e`.

source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

# ACVP ML-KEM keyGen (bc-test-data/pqc/crypto/mlkem/ML-KEM-keyGen.txt, ML-KEM-512 tcId 1): the
# 64-byte seed is d || z (FIPS 203 Alg 19 draws d then z; Alg 16 takes (d, z)); `keygen-from-seed`
# must give the vector's dk and `pk-from-sk` its ek, from the seed as raw bytes and as hex.
test_mlkem512_keygen_from_seed_matches_acvp() {
    local got
    unhex 8A3D5F46A59A1B14E87C963A355D12D353074754FF15000172E6C8AE00A3AC1D5449ACE5765E87F252DD14DED32FD1973DF5B5DE53751A3723D5A52C8C6DF2FD >"$TMP/seed"
    assert_size "$TMP/seed" 64 "seed length"
    got=$(hex_out "$BC_RUST" mlkem512 keygen-from-seed -x <"$TMP/seed")
    assert_eq "$got" "" "dk from a raw seed"
    got=$(printf '%s' 8A3D5F46A59A1B14E87C963A355D12D353074754FF15000172E6C8AE00A3AC1D5449ACE5765E87F252DD14DED32FD1973DF5B5DE53751A3723D5A52C8C6DF2FD | hex_out "$BC_RUST" --hex-input mlkem512 keygen-from-seed -x)
    assert_eq "$got" "" "dk from a hex seed"
    "$BC_RUST" mlkem512 keygen-from-seed <"$TMP/seed" >"$TMP/dk"
    got=$(hex_out "$BC_RUST" mlkem512 pk-from-sk -x <"$TMP/dk")
    assert_eq "$got" "" "ek from the dk"
    expect_ok "the pair must be consistent" "$BC_RUST" mlkem512 check-consistency --pkfile <(unhex ) <"$TMP/dk" >/dev/null
}

# ACVP ML-KEM encapDecap, decapsulation (ML-KEM-encapDecap.txt, ML-KEM-512 tcId 26): dk and c give k.
test_mlkem512_decaps_matches_acvp() {
    local got
    unhex  >"$TMP/dk"
    unhex  >"$TMP/c"
    got=$(hex_out "$BC_RUST" mlkem512 decaps --skfile "$TMP/dk" -x <"$TMP/c")
    assert_eq "$got" "afb1789cf2bf24b4d0cd0e94570fe0da6dcc7a082286cfad97c59195679cedda" "shared secret (ct on stdin)"
    got=$(hex_out "$BC_RUST" mlkem512 decaps --skfile "$TMP/dk" --ctfile "$TMP/c" -x </dev/null)
    assert_eq "$got" "afb1789cf2bf24b4d0cd0e94570fe0da6dcc7a082286cfad97c59195679cedda" "shared secret (ct from --ctfile)"
    printf '%s'  >"$TMP/dk.hex"
    got=$(hex "$TMP/c" | hex_out "$BC_RUST" --hex-input mlkem512 decaps --skfile "$TMP/dk.hex" -x)
    assert_eq "$got" "afb1789cf2bf24b4d0cd0e94570fe0da6dcc7a082286cfad97c59195679cedda" "shared secret (hex dk file and hex ct, with --hex-input)"
}

# `keygen` draws from the OS; its output must be a ML-KEM-512 key (FIPS 203 Table 3 dk length), and
# encaps/decaps with it must agree on the shared secret through --ctfile and through stdout.
test_mlkem512_keygen_encaps_decaps_round_trip() {
    local ss_enc ss_dec lines
    "$BC_RUST" mlkem512 keygen >"$TMP/dk"
    assert_size "$TMP/dk" 1632 "dk length of ML-KEM-512"
    "$BC_RUST" mlkem512 pk-from-sk --skfile "$TMP/dk" >"$TMP/ek"
    assert_size "$TMP/ek" 800 "ek length of ML-KEM-512"
    expect_ok "the pair must be consistent" "$BC_RUST" mlkem512 check-consistency --skfile "$TMP/dk" --pkfile "$TMP/ek" </dev/null >/dev/null
    # `-x` would also render the --ctfile as hex ("the ciphertext to file also in binary or hex"), so the
    # secret is hex-encoded here and the ciphertext file stays binary.
    ss_enc=$("$BC_RUST" mlkem512 encaps --pkfile "$TMP/ek" --ctfile "$TMP/ct" </dev/null | "$BC_RUST" hex-encode)
    assert_size "$TMP/ct" 768 "ct length of ML-KEM-512"
    ss_dec=$(hex_out "$BC_RUST" mlkem512 decaps --skfile "$TMP/dk" -x <"$TMP/ct")
    assert_eq "$ss_dec" "$ss_enc" "decaps must recover the encapsulated secret"
    lines=$("$BC_RUST" mlkem512 encaps --pkfile "$TMP/ek" | wc -l | tr -d ' ')
    assert_eq "$lines" 1 "without --ctfile, ct and ss are two hex lines separated by one newline"
}

